  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": [
        "C25"
      ],
      "claim": "Milvexian 25-mg SDD had an absolute bioavailability of 58.2% (95% CI 52.8–70.7%) under fasted conditions relative to an IV microtracer, supporting F ≥ 20%."
    },
    {
      "card_ids": [
        "C02"
      ],
      "claim": "Ketanserin 40-mg tablet had an absolute bioavailability of 60% in fasted subjects, supporting F ≥ 20%."
    },
    {
      "card_ids": [
        "C27"
      ],
      "claim": "LCB01-0371 (delpazolid) had a mean absolute oral bioavailability of 99.75% after an 800-mg oral dose, strongly supporting high F."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [
    "C20"
  ],
  "decision_summary": "All retrieved evidence molecules show absolute oral bioavailability values well above the 20% threshold, including direct fasted measurements of 58.2% and 60%; therefore, the query is predicted to have high bioavailability.",
  "evidence_gaps": [
    "Most supporting records were not explicitly collected under fasted conditions, though direct fasted absolute F values are available for milvexian and ketanserin.",
    "Pradigastat records conflict between a numeric ~40% absolute bioavailability and qualitative 'completely bioavailable' reports.",
    "One ketanserin record reports a wide 15–60% bioavailability range, but the fasted absolute measurement is 60%."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": [
    "C25",
    "C02",
    "C27"
  ],
  "revision_action": "initial",
  "supportive_card_ids": [
    "C25",
    "C02",
    "C27"
  ]
}

